using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Security.Cryptography;using System.Text;using System.Threading;using Newtonsoft.Json;using Newtonsoft.Json.Linq;using SpatialWallpaper.Sdk.Hosting;
namespace SpatialWallpaper.Sdk.Hosting {
 public static class TrustedRuntimeDistribution {
  internal static JObject Read(string path,int limit){var info=new FileInfo(path);if(info.Length<1||info.Length>limit||(info.Attributes&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("trusted-json-file");using(var text=new StringReader(File.ReadAllText(path,new UTF8Encoding(false,true))))using(var reader=new JsonTextReader(text){MaxDepth=12,DateParseHandling=DateParseHandling.None}){var value=JObject.Load(reader,new JsonLoadSettings{DuplicatePropertyNameHandling=DuplicatePropertyNameHandling.Error});if(reader.Read())throw new InvalidDataException("trusted-json-tail");return value;}}
  internal static void Fields(JObject value,params string[] names){if(value==null||!value.Properties().Select(p=>p.Name).OrderBy(n=>n,StringComparer.Ordinal).SequenceEqual(names.OrderBy(n=>n,StringComparer.Ordinal)))throw new InvalidDataException("trusted-configuration-fields");}
  internal static string Text(JToken value){if(value?.Type!=JTokenType.String||((string)value).Length<1||((string)value).Length>2048||((string)value).IndexOf('\0')>=0)throw new InvalidDataException("trusted-configuration-text");return (string)value;}
  internal static int Integer(JToken value){if(value?.Type!=JTokenType.Integer)throw new InvalidDataException("trusted-configuration-integer");return (int)value;}
  internal static float Number(JToken value){if(value?.Type!=JTokenType.Float&&value?.Type!=JTokenType.Integer)throw new InvalidDataException("trusted-configuration-number");float number=(float)value;if(float.IsNaN(number)||float.IsInfinity(number))throw new InvalidDataException("trusted-configuration-number");return number;}
  static void NoLinkedAncestors(string path){for(var directory=new DirectoryInfo(path);directory!=null;directory=directory.Parent)if((directory.Attributes&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("runtime-distribution-link");}
  static void CanonicalSegment(string segment){
   if(segment.Length==0||segment=="."||segment==".."||segment.EndsWith(".",StringComparison.Ordinal)||segment.EndsWith(" ",StringComparison.Ordinal)||segment.IndexOfAny(Path.GetInvalidFileNameChars())>=0)throw new InvalidDataException("runtime-distribution-path");
   string stem=segment.Split('.')[0].ToUpperInvariant();
   if(new[]{"CON","PRN","AUX","NUL","CONIN$","CONOUT$"}.Contains(stem)||(stem.Length==4&&(stem.StartsWith("COM",StringComparison.Ordinal)||stem.StartsWith("LPT",StringComparison.Ordinal))&&"123456789¹²³".Contains(stem[3])))throw new InvalidDataException("runtime-distribution-device");
  }
  static void WorkerInventory(string root,JObject files){
   var report=Read(Path.Combine(root,"worker","report.json"),2*1024*1024);var inventory=report["runtime_files"] as JObject;
   if(inventory==null||inventory.Count<1||inventory.Count>8192||inventory["Worker.exe"]==null)throw new InvalidDataException("runtime-worker-inventory");
   var names=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
   foreach(var file in inventory.Properties()){
    string name=file.Name,digest=Text(file.Value);if(!names.Add(name)||name.Length>240||name.Contains('\\')||name.Contains(':')||name.StartsWith("/",StringComparison.Ordinal)||digest.Length!=64||digest.Any(c=>!(c>='0'&&c<='9'||c>='a'&&c<='f')))throw new InvalidDataException("runtime-worker-inventory-path");
    foreach(string segment in name.Split('/'))CanonicalSegment(segment);
    if(files["worker/player/"+name]?.Type!=JTokenType.String||(string)files["worker/player/"+name]!=digest)throw new InvalidDataException("runtime-worker-inventory-missing:"+name);
   }
   foreach(var file in files.Properties())if(file.Name.StartsWith("worker/player/",StringComparison.Ordinal)&&inventory[file.Name.Substring("worker/player/".Length)]==null)throw new InvalidDataException("runtime-worker-inventory-extra:"+file.Name);
  }
  static void CompleteInventory(string root,HashSet<string> files,CancellationToken cancellation){
   var pending=new Stack<string>();pending.Push(root);int count=0;
   while(pending.Count!=0)foreach(string path in Directory.EnumerateFileSystemEntries(pending.Pop())){
    cancellation.ThrowIfCancellationRequested();if(++count>16384)throw new InvalidDataException("runtime-distribution-entry-count");var attributes=File.GetAttributes(path);if((attributes&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("runtime-distribution-link");
    if((attributes&FileAttributes.Directory)!=0){pending.Push(path);continue;}string relative=path.Substring(root.TrimEnd(Path.DirectorySeparatorChar).Length+1).Replace(Path.DirectorySeparatorChar,'/');
    if(relative.Equals("runtime.json",StringComparison.OrdinalIgnoreCase))continue;if(!files.Contains(relative))throw new InvalidDataException("runtime-distribution-unlisted:"+relative);
   }
  }
  public static JObject Verify(string root,IDictionary<string,string> identity,string executablePath,CancellationToken cancellation){
   if(identity==null||identity.Count!=7||new[]{"sdk","engine","pipeline","vm","backend","rules_sha256","policy_id"}.Any(key=>!identity.ContainsKey(key))||identity["rules_sha256"]!=CapabilityNames.RulesDigest||identity["policy_id"]!=RuntimeLimits.Id)throw new ArgumentException("runtime-expected-identity");root=Path.GetFullPath(root);NoLinkedAncestors(root);if(!string.Equals(Path.GetFullPath(executablePath),Path.Combine(root,"SpatialWallpaper.Preview.exe"),StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("runtime-distribution-executable-location");if((File.GetAttributes(root)&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("runtime-distribution-link");var manifest=Read(Path.Combine(root,"runtime.json"),2*1024*1024);Fields(manifest,"format","kind","sdk","engine","pipeline","vm","backend","rules_sha256","policy_id","stage","files");if(Integer(manifest["format"])!=1||Text(manifest["kind"])!="spatialwallpaper-runtime"||Text(manifest["rules_sha256"])!=CapabilityNames.RulesDigest||Text(manifest["policy_id"])!=RuntimeLimits.Id)throw new InvalidDataException("runtime-distribution-identity");foreach(string key in new[]{"sdk","engine","pipeline","vm","backend"})if(Text(manifest[key])!=identity[key])throw new InvalidDataException("runtime-distribution-version:"+key);string stage=Text(manifest["stage"]);if(stage!="development"&&stage!="rc")throw new InvalidDataException("runtime-distribution-stage");var files=manifest["files"] as JObject;if(files==null||files.Count<1||files.Count>8192)throw new InvalidDataException("runtime-distribution-file-count");
   foreach(string required in new[]{"SpatialWallpaper.Preview.exe","SpatialWallpaper.Preview.exe.config","Newtonsoft.Json.dll","supervisor/Supervisor.exe","supervisor/build.json","validator/Validator.exe","validator/build.json","worker/report.json","worker/player/Worker.exe"})if(files[required]==null)throw new InvalidDataException("runtime-distribution-file-missing:"+required);
   var names=new HashSet<string>(StringComparer.OrdinalIgnoreCase);string boundary=root.TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;
   foreach(var file in files.Properties()){cancellation.ThrowIfCancellationRequested();string name=file.Name,digest=Text(file.Value);if(!names.Add(name)||name.Length>240||name.Contains('\\')||name.Contains(':')||name.StartsWith("/",StringComparison.Ordinal)||digest.Length!=64||digest.Any(c=>!(c>='0'&&c<='9'||c>='a'&&c<='f')))throw new InvalidDataException("runtime-distribution-path-or-digest");string path=root;foreach(string segment in name.Split('/')){CanonicalSegment(segment);path=Path.Combine(path,segment);if((File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("runtime-distribution-link");}if(!Path.GetFullPath(path).StartsWith(boundary,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("runtime-distribution-boundary");using(var input=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read))using(var sha=SHA256.Create())if(BitConverter.ToString(sha.ComputeHash(input)).Replace("-","").ToLowerInvariant()!=digest)throw new InvalidDataException("runtime-distribution-drift:"+name);}
   WorkerInventory(root,files);CompleteInventory(root,names,cancellation);HostExitContract.Require(Path.Combine(root,"supervisor","Supervisor.exe"));return manifest;
  }
 }
}
